import{_ as t,o,c as a,a2 as l}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"CC Switch 接入 Claude Code CLI：终端 AI 编程助手用上中转站","description":"","frontmatter":{"title":"CC Switch 接入 Claude Code CLI：终端 AI 编程助手用上中转站","date":"2026-09-18T20:00:00.000Z","tags":["CC Switch","Claude Code","中转站","教程"],"categories":["技术折腾"]},"headers":[],"relativePath":"guide/03-claude-code-cli.md","filePath":"guide/03-claude-code-cli.md"}'),d={name:"guide/03-claude-code-cli.md"};function i(c,e,s,n,r,u){return o(),a("div",null,[...e[0]||(e[0]=[l('<blockquote><p>生命不息，折腾不止。</p></blockquote><p>Claude Code 是现在最火的终端 AI 编程助手。这篇教小白：用 CC Switch 把 AI 中转站接进 Claude Code CLI，不用 Anthropic 官方账号、不用绑海外卡，一个 Key 就能在终端里用上 Claude 全家桶。</p><h2 id="一、claude-code-cli-是什么" tabindex="-1">一、Claude Code CLI 是什么 <a class="header-anchor" href="#一、claude-code-cli-是什么" aria-label="Permalink to &quot;一、Claude Code CLI 是什么&quot;">​</a></h2><p>Claude Code 跑在终端（命令行）里，你打字问它，它帮你读代码、改代码、跑命令，是程序员的新宠。</p><p>它官方只认 Anthropic 账号，配置存在 <code>~/.claude/settings.json</code> 里（一堆 JSON，小白看不懂）。<strong>CC Switch 就是帮你看懂它、一键改它</strong>的小工具。</p><h2 id="二、准备工作" tabindex="-1">二、准备工作 <a class="header-anchor" href="#二、准备工作" aria-label="Permalink to &quot;二、准备工作&quot;">​</a></h2><blockquote></blockquote><p>（2 分钟）</p><ol><li><strong>中转站 API Key</strong>：登录你的中转站（如 ai.aklibk.com）→ 后台 → API Keys → 创建，复制 <code>sk-</code> 开头的 Key</li><li><strong>Node.js</strong>：nodejs.org 装 LTS 版，cmd 里 <code>node --version</code> 验证</li><li><strong>装 Claude Code</strong>：终端执行<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm install -g @anthropic-ai/claude-code</span></span></code></pre></div>下载慢就换镜像：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm install -g @anthropic-ai/claude-code --registry=https://registry.npmmirror.com</span></span></code></pre></div></li></ol><h2 id="三、在-cc-switch-里添加供应商" tabindex="-1">三、在 CC Switch 里添加供应商 <a class="header-anchor" href="#三、在-cc-switch-里添加供应商" aria-label="Permalink to &quot;三、在 CC Switch 里添加供应商&quot;">​</a></h2><ol><li>打开 CC Switch（官网 ccswitch.io 或 GitHub Releases 下载）</li><li>左侧切换器选 <strong>Claude</strong> 应用（图标右下角没小方块的就是 CLI 版）</li><li>点右上角 <strong>+</strong> 号</li><li>预设选 <strong>自定义</strong></li><li>填三个关键信息： <ul><li><strong>名称</strong>：如 <code>我的中转站</code></li><li><strong>API 地址（Base URL）</strong>：填 <code>https://ai.aklibk.com</code>（中转站文档为准，有的要带 <code>/v1</code>）</li><li><strong>API Key</strong>：粘贴中转站的 Key</li></ul></li><li>点模型框旁的 <strong>获取模型</strong> 按钮自动拉列表，或手动填（如 <code>claude-sonnet-4-5</code>）</li><li>点 <strong>添加</strong></li></ol><blockquote></blockquote><blockquote><p>CC Switch 会自动把 <code>ANTHROPIC_API_KEY</code> 和 <code>ANTHROPIC_BASE_URL</code> 写进 <code>~/.claude/settings.json</code>，全程你不用看 JSON。</p></blockquote><h2 id="四、切换并运行-claude-code" tabindex="-1">四、切换并运行 Claude Code <a class="header-anchor" href="#四、切换并运行-claude-code" aria-label="Permalink to &quot;四、切换并运行 Claude Code&quot;">​</a></h2><ol><li>在 CC Switch 的 Claude 面板点一下刚添加的供应商（选中）</li><li>打开终端，输入：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude</span></span></code></pre></div></li><li>问一句&quot;你好&quot;——能回复就成功了</li></ol><blockquote></blockquote><p><strong>想切回官方账号？</strong> 点回「Claude 官方」供应商即可。</p><h2 id="五、常见问题" tabindex="-1">五、常见问题 <a class="header-anchor" href="#五、常见问题" aria-label="Permalink to &quot;五、常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>解决</th></tr></thead><tbody><tr><td>报 401</td><td>API 地址或 Key 填错，回去核对</td></tr><tr><td>拉不到模型</td><td>手动填模型名</td></tr><tr><td>想换模型</td><td>回 CC Switch 编辑供应商改模型，再点一下切换</td></tr><tr><td>报错看不懂</td><td>终端跑 <code>claude doctor</code> 看诊断</td></tr></tbody></table><h2 id="六、总结" tabindex="-1">六、总结 <a class="header-anchor" href="#六、总结" aria-label="Permalink to &quot;六、总结&quot;">​</a></h2><p>Claude Code CLI 接中转站：<strong>下载 CC Switch → Claude 面板添加（填地址+Key）→ 点一下切换 → 终端跑 claude</strong>。</p><p>Claude、GPT、Gemini 全家桶一个 Key 通吃？试试 Aklibk API 中转站（ai.aklibk.com），国内直连、免绑卡、人民币按量付费。</p><blockquote><p>下一篇预告：Claude Desktop 桌面客户端的接入教程，注意它和 CLI 的配置不是一回事。</p></blockquote>',23)])])}const C=t(d,[["render",i]]);export{p as __pageData,C as default};
